    let isPovMode = false;
    let isTransitioning = false;
    let isOrderManagerBuilt = false;
    const themeColorMap = { light: { bg: '#f8f6f2', text: '#3d3b37' }, dark: { bg: '#1f1d1b', text: '#e0ddd8' }, dusk: { bg: '#f3eade', text: '#5d4037' }, twilight: { bg: '#0d0f12', text: '#eaf0f2' }, parchment: { bg: '#fdf5e6', text: '#5d4037' } };
    function applyThemeButtonColors() { themeSwitchBtns.forEach(btn => { const themeName = btn.dataset.theme; if (themeColorMap[themeName]) { btn.style.backgroundColor = themeColorMap[themeName].bg; btn.style.color = themeColorMap[themeName].text; } }); }
    function checkPovContent() { if (toggleBtn && povContentArea && (!povContentArea.textContent || povContentArea.textContent.trim() === '')) { toggleBtn.style.display = 'none'; } }
    function toggleView() { if (isTransitioning) return; isTransitioning = true; isPovMode = !isPovMode; const currentView = isPovMode ? mainView : povView; const nextView = isPovMode ? povView : mainView; currentView.classList.add('is-exiting'); currentView.addEventListener('animationend', function onExitAnimationEnd() { this.removeEventListener('animationend', onExitAnimationEnd); this.classList.add('is-hidden'); this.classList.remove('is-exiting'); nextView.classList.remove('is-hidden'); requestAnimationFrame(() => { nextView.classList.add('is-entering'); nextView.addEventListener('animationend', function onEnterAnimationEnd() { this.removeEventListener('animationend', onEnterAnimationEnd); this.classList.remove('is-entering'); isTransitioning = false; }, { once: true }); }); }, { once: true }); }
    if(toggleBtn) toggleBtn.addEventListener('click', toggleView);
    if(menuOpenBtn) menuOpenBtn.addEventListener('click', () => popupMenu.classList.add('active'));
    if(menuCloseBtn) menuCloseBtn.addEventListener('click', () => popupMenu.classList.remove('active'));
    if(popupMenu) popupMenu.addEventListener('click', (e) => { if (e.target === popupMenu) popupMenu.classList.remove('active'); });
    const updateSliderBackground = (slider) => { const value = (slider.value - slider.min) / (slider.max - slider.min) * 100; const textColor = getComputedStyle(slider).getPropertyValue('--text-primary').trim(); const borderColor = getComputedStyle(slider).getPropertyValue('--border-color').trim(); slider.style.background = `linear-gradient(to right, ${textColor} ${value}%, ${borderColor} ${value}%)`; };
    const applyFontSize = (size) => { const numericSize = parseInt(size, 10); const allScrollAreas = document.querySelectorAll('.scroll-area-v17'); allScrollAreas.forEach(area => area.style.fontSize = `${numericSize}px`); if(fontSizeLabel) fontSizeLabel.textContent = `字体大小: ${numericSize}px`; localStorage.setItem('narrativeFontSize_v17', numericSize); if(fontSizeSlider) updateSliderBackground(fontSizeSlider); };
    if(fontSizeSlider) { fontSizeSlider.addEventListener('input', (e) => { applyFontSize(e.target.value); }); }
    const applyTheme = (theme) => { if(container) { container.className = 'narrative-container-v17'; container.classList.add(`theme-${theme}`); } themeSwitchBtns.forEach(btn => btn.classList.toggle('active', btn.dataset.theme === theme)); localStorage.setItem('narrativeTheme_v17', theme); setTimeout(() => { if(fontSizeSlider) updateSliderBackground(fontSizeSlider); }, 50); };
    themeSwitchBtns.forEach(btn => btn.addEventListener('click', () => applyTheme(btn.dataset.theme)));
    if (dataStatusbarToggleBtn && dataStatusbar) { dataStatusbarToggleBtn.addEventListener('click', function() { const isExpanded = dataStatusbar.classList.toggle('expanded'); if(isExpanded) { initDataStatusDisplay(); } if (textStatusbar) textStatusbar.classList.remove('expanded'); if (orderManagerStatusbar) orderManagerStatusbar.classList.remove('expanded'); }); }
    if (textStatusbarToggleBtn && textStatusbar) { textStatusbarToggleBtn.addEventListener('click', function() { const isExpanded = textStatusbar.classList.toggle('expanded'); if(isExpanded) { initTextStatusDisplay(); } if (dataStatusbar) dataStatusbar.classList.remove('expanded'); if (orderManagerStatusbar) orderManagerStatusbar.classList.remove('expanded'); }); }
    if (orderManagerToggleBtn && orderManagerStatusbar) { orderManagerToggleBtn.addEventListener('click', function() { const isExpanded = orderManagerStatusbar.classList.toggle('expanded'); if(isExpanded) { loadOrderData(); } if (dataStatusbar) dataStatusbar.classList.remove('expanded'); if (textStatusbar) textStatusbar.classList.remove('expanded'); }); }

    function initTextStatusDisplay() {
        const sourceElement = document.getElementById('status-block-source');
        const contentElement = document.getElementById('text-status-content');
        if (!sourceElement || !contentElement) return;
        contentElement.innerHTML = '';
        const rawText = sourceElement.textContent || '';
        if (!rawText.trim()) {
            contentElement.innerHTML = '<div class="status-item"><span class="status-item-value">暂无状态信息。</span></div>';
            return;
        }
        const lines = rawText.trim().split('\n');
        lines.forEach(line => {
            line = line.trim();
            if (line) {
                const parts = line.split(/[:：]/);
                const label = parts[0] ? parts[0].trim() : '';
                const value = parts.length > 1 ? parts.slice(1).join(':').trim() : '';
                const itemDiv = document.createElement('div');
                itemDiv.className = 'status-item';
                const labelSpan = document.createElement('span');
                labelSpan.className = 'status-item-label';
                labelSpan.textContent = label ? label + '：' : '';
                const valueSpan = document.createElement('span');
                valueSpan.className = 'status-item-value';
                valueSpan.textContent = value;
                itemDiv.appendChild(labelSpan);
                itemDiv.appendChild(valueSpan);
                contentElement.appendChild(itemDiv);
            }
        });
    }
    function SafeGetValue(obj, path, defaultValue = "N/A") { let keys = Array.isArray(path) ? path : path.split('.'); let current = obj; for (let i = 0; i < keys.length; i++) { if (current === undefined || current === null || typeof current !== 'object' || !current.hasOwnProperty(keys[i])) { return defaultValue; } current = current[keys[i]]; } if (current === undefined || current === null) { return defaultValue; } if (Array.isArray(current)) { if (current.length > 0) { const actualValue = current[0]; if (typeof actualValue === 'boolean') { return actualValue; } return String(actualValue); } else { return defaultValue; } } if (typeof current === 'boolean') { return current; } return String(current); }
    function updateProgressBar(barId, valueMainId, valueDescId, rawValueFromCharacterData, min, max) { const progressBar = document.getElementById(barId); const valueMainDisplay = document.getElementById(valueMainId); const valueDescDisplay = document.getElementById(valueDescId); if (!valueMainDisplay) return; let fullDisplayString = SafeGetValue({ temp: rawValueFromCharacterData }, 'temp', String(min)); let numericValue = min; let descriptionText = ""; const descriptionMatch = String(fullDisplayString).match(/\((.+)\)$/); if (descriptionMatch && descriptionMatch[1]) { descriptionText = descriptionMatch[1]; fullDisplayString = String(fullDisplayString).substring(0, descriptionMatch.index).trim(); } const valueMatch = String(fullDisplayString).match(/(-?\d+(\.\d+)?)(?=[^\d.]*$|->)/); if (valueMatch) { numericValue = parseFloat(valueMatch[1]); const parts = String(fullDisplayString).split('->'); valueMainDisplay.innerText = parts.length > 1 ? parts[1].trim() : parts[0].trim(); } else if (!isNaN(parseFloat(fullDisplayString))) { numericValue = parseFloat(fullDisplayString); valueMainDisplay.innerText = fullDisplayString; } else { valueMainDisplay.innerText = SafeGetValue({ temp: rawValueFromCharacterData }, 'temp', String(min)); } if (valueDescDisplay) { valueDescDisplay.innerText = descriptionText ? `(${descriptionText})` : ""; } if (progressBar) { numericValue = Math.max(min, Math.min(max, numericValue)); const range = max - min; const percentage = range === 0 ? (numericValue >= max ? 100 : 0) : ((numericValue - min) / range) * 100; progressBar.style.width = `${Math.max(0, Math.min(100, percentage))}%`; } }
    function updateTextValue(elementId, rawValueFromCharacterData, defaultValue) { const element = document.getElementById(elementId); if(element) { element.innerText = SafeGetValue({ temp: rawValueFromCharacterData }, 'temp', defaultValue); } }
    async function initDataStatusDisplay() { try { const messages = await getChatMessages(getCurrentMessageId()); if (!messages || messages.length === 0 || !messages[messages.length - 1].data) return; const gameData = messages[messages.length - 1].data; const characterData = gameData.stat_data; if (!characterData) return; if (characterData.hasOwnProperty('桃子')) { updateProgressBar('momoko-affection-bar', 'momoko-affection', 'momoko-affection-desc', SafeGetValue(characterData, '桃子.好感度'), 0, 100); updateProgressBar('momoko-ntr-bar', 'momoko-ntr', 'momoko-ntr-desc', SafeGetValue(characterData, '桃子.寝取度'), 0, 100); updateProgressBar('momoko-loyalty-bar', 'momoko-loyalty', 'momoko-loyalty-desc', SafeGetValue(characterData, '桃子.对丈夫的忠诚度'), 0, 100); updateTextValue('momoko-mental-state', SafeGetValue(characterData, '桃子.内心状态'), '未知'); } if (characterData.hasOwnProperty('小柴俊')) { updateProgressBar('takeshi-recovery-bar', 'takeshi-recovery', 'takeshi-recovery-desc', SafeGetValue(characterData, '小柴俊.康复度'), 0, 100); updateProgressBar('takeshi-confidence-bar', 'takeshi-confidence', 'takeshi-confidence-desc', SafeGetValue(characterData, '小柴俊.对计划的信心'), 0, 100); updateTextValue('takeshi-mental-state', SafeGetValue(characterData, '小柴俊.心理状态'), '未知'); } if (characterData.hasOwnProperty('互动')) { updateProgressBar('interaction-sex-progress-bar', 'interaction-sex-progress', 'interaction-sex-progress-desc', SafeGetValue(characterData, '互动.性爱进度'), 0, 8); updateProgressBar('interaction-privacy-bar', 'interaction-privacy', 'interaction-privacy-desc', SafeGetValue(characterData, '互动.私密程度'), 1, 5); } if (characterData.hasOwnProperty('世界')) { updateTextValue('world-story-stage', SafeGetValue(characterData, '世界.故事阶段'), '未知'); updateTextValue('world-current-time', SafeGetValue(characterData, '世界.当前时间'), '未知'); } } catch (error) { const statusbarElement = document.getElementById('data-statusbar-v17'); if(statusbarElement) statusbarElement.innerHTML = `<p style='color:red; padding:10px;'>状态栏加载出错: ${error.message}</p>`; } }

    // --- 指令管理器JS逻辑 ---
    let orderData = { orderList: [], originalList: [], hasModifications: false };
    function buildOrderManagerUI() {
        const container = document.getElementById('order-manager-container');
        container.innerHTML = `
            <div class="om-manager-header">
                <h2>指令管理</h2>
                <div class="om-status-indicator">
                    <div class="om-status-dot"></div>
                    <span>已连接</span>
                </div>
            </div>
            <div class="om-manager-body">
                <div class="om-debug-area" id="om-debug-area">
                    <div class="om-debug-header">
                        <h3>原始数据观测区</h3>
                    </div>
                    <div class="om-debug-content">
                        <small>指令列表 (Raw):</small>
                        <pre id="om-debug-all"></pre>
                        <small>当前激活 (Raw):</small>
                        <pre id="om-debug-active"></pre>
                        <small>未激活 (Raw):</small>
                        <pre id="om-debug-inactive"></pre>
                    </div>
                </div>
                <div class="om-order-list">
                    <div class="om-order-list-header">
                        <span class="om-order-list-title">指令列表</span>
                        <span class="om-order-count" id="om-order-count">0 / 0</span>
