    function toggleOmDebugArea() { const debugArea = document.getElementById('om-debug-area'); if(debugArea) { const isCollapsed = debugArea.classList.toggle('collapsed'); localStorage.setItem('omDebugAreaCollapsed', isCollapsed); } }
    function extractOrderContent(aomString) { if (!aomString || typeof aomString !== 'string') return ""; const match = aomString.match(/丨(.+?)\/\/ admin\.order::亅/); return match ? match[1].trim() : aomString; }
    function wrapOrderContent(content) { if (!content) return ""; return `丨${content.trim()}// admin.order::亅`; }
    function parseAomStringToArray(aomString) { if (!aomString || typeof aomString !== 'string') return []; const regex = /丨.+?\/\/ admin\.order::亅/g; return aomString.match(regex) || []; }
    function arrayToAomString(aomArray) { if (!Array.isArray(aomArray)) return ""; return aomArray.join(''); }
    function updateOmModifiedIndicator() { const indicator = document.getElementById('om-modified-indicator'); if(indicator) indicator.style.display = orderData.hasModifications ? 'inline-block' : 'none'; }
    function markOmAsModified() { orderData.hasModifications = true; updateOmModifiedIndicator(); }
    function renderOrderList() {
        const container = document.getElementById('om-order-list-container');
        const countElement = document.getElementById('om-order-count');
        if (!container || !countElement) return;
        const list = orderData.orderList;
        if (!Array.isArray(list) || list.length === 0) { container.innerHTML = '<div class="om-empty-state">暂无指令</div>'; countElement.textContent = '0 / 0'; return; }
        const activeCount = list.filter(item => item.isActive).length;
        countElement.textContent = `${activeCount} / ${list.length}`;
        const html = list.map((order, index) => {
            const content = extractOrderContent(order.content);
            return `<div class="om-order-item ${order.isActive ? 'active' : ''}" data-index="${index}"> <div class="om-order-header"> <div class="om-order-status"> <span class="om-order-index">#${index + 1}</span> <label class="om-switch"> <input type="checkbox" ${order.isActive ? 'checked' : ''}> <span class="om-slider"></span> </label> </div> <div class="om-order-actions"> <button class="om-btn om-btn-edit">编辑</button> <button class="om-btn om-btn-delete">删除</button> </div> </div> <div class="om-order-content"> <div class="om-order-text">${content || '(空指令)'}</div> </div> </div>`;
        }).join('');
        container.innerHTML = html;

        // 为新生成的元素绑定事件
        container.querySelectorAll('.om-order-item').forEach((item, index) => {
            item.querySelector('input[type="checkbox"]').addEventListener('change', () => toggleOmOrderStatus(index));
            item.querySelector('.om-btn-edit').addEventListener('click', () => editOmOrder(index));
            item.querySelector('.om-btn-delete').addEventListener('click', () => deleteOmOrder(index));
        });
    }
    function toggleOmOrderStatus(index) { if (orderData.orderList[index]) { orderData.orderList[index].isActive = !orderData.orderList[index].isActive; markOmAsModified(); renderOrderList(); } }
    function editOmOrder(index) {
        const orderItem = document.querySelector(`.om-order-item[data-index="${index}"]`);
        if (!orderItem) return;
        const content = extractOrderContent(orderData.orderList[index].content);
        orderItem.classList.add('editing');
        const contentDiv = orderItem.querySelector('.om-order-content');
        contentDiv.innerHTML = `<textarea class="om-order-edit-area">${content}</textarea> <div style="margin-top: 8px; display: flex; gap: 6px;"> <button class="om-btn om-btn-save">保存</button> <button class="om-btn om-btn-cancel">取消</button> </div>`;
        contentDiv.querySelector('.om-btn-save').addEventListener('click', () => saveOmOrder(index));
        contentDiv.querySelector('.om-btn-cancel').addEventListener('click', cancelOmEdit);
    }
    function saveOmOrder(index) { const textarea = document.querySelector(`.om-order-item[data-index="${index}"] .om-order-edit-area`); const newContent = textarea.value.trim(); orderData.orderList[index].content = wrapOrderContent(newContent); markOmAsModified(); renderOrderList(); }
    function cancelOmEdit() { renderOrderList(); }
    function deleteOmOrder(index) { if (confirm(`确定要删除指令 #${index + 1} 吗？`)) { orderData.orderList.splice(index, 1); markOmAsModified(); renderOrderList(); } }
    function addOmOrder() { const input = document.getElementById('om-new-order-input'); if(!input) return; const content = input.value.trim(); if (content) { orderData.orderList.push({ content: wrapOrderContent(content), isActive: false }); input.value = ''; markOmAsModified(); renderOrderList(); } }
    function confirmOmModifications() {
        if (!orderData.hasModifications) { alert('没有需要提交的修改。'); return; }
        const activeOrders = orderData.orderList.filter(item => item.isActive).map(item => item.content);
        const inactiveOrders = orderData.orderList.filter(item => !item.isActive).map(item => item.content);
        const allOrders = orderData.orderList.map(item => item.content);
        const activeOrdersString = arrayToAomString(activeOrders);
        const inactiveOrdersString = arrayToAomString(inactiveOrders);
        const allOrdersString = arrayToAomString(allOrders);
        const injectionText = `<!-- {{mvu.set::{"path":"叙事指令.当前激活指令","value":"${activeOrdersString}"} }} -->\n<!-- {{mvu.set::{"path":"叙事指令.未激活指令","value":"${inactiveOrdersString}"} }} -->\n<!-- {{mvu.set::{"path":"叙事指令.指令列表","value":"${allOrdersString}"} }} -->`;
        try {
            if (typeof SillyTavern !== 'undefined' && SillyTavern.getContext) {
                const context = SillyTavern.getContext();
                context.sendSystemMessage({ type: 'system', is_system: true, is_user: false, send_date: Date.now(), mes: injectionText });
                alert('指令已成功注入！AI将在下一次回复中处理。');
            } else if (typeof triggerSlash === 'function') {
                triggerSlash(`/send ${injectionText}`);
                alert('指令已成功注入！AI将在下一次回复中处理。');
            } else {
                navigator.clipboard.writeText(injectionText).then(() => { alert('无法自动注入。指令内容已复制到剪贴板，请手动粘贴到对话框中发送。'); });
            }
            orderData.originalList = JSON.parse(JSON.stringify(orderData.orderList));
            orderData.hasModifications = false;
            updateOmModifiedIndicator();
        } catch (e) { console.error("注入失败:", e); alert("注入指令时发生错误，请查看控制台。"); }
    }
    function resetOmChanges() { if (orderData.hasModifications && !confirm('您有未保存的更改，确定要重置吗？')) { return; } orderData.orderList = JSON.parse(JSON.stringify(orderData.originalList)); orderData.hasModifications = false; updateOmModifiedIndicator(); renderOrderList(); }
    async function loadOrderData() {
        if (!isOrderManagerBuilt) {
            buildOrderManagerUI();
        }
        const container = document.getElementById('om-order-list-container');
        try {
            const messages = await getChatMessages(getCurrentMessageId());
            if (!messages || messages.length === 0 || !messages[messages.length - 1].data) { container.innerHTML = '<div class="om-empty-state">无数据</div>'; return; }
            const gameData = messages[messages.length - 1].data;
            const characterData = gameData.stat_data;
            if (characterData && characterData.叙事指令) {
                const allOrdersString = SafeGetValue(characterData, '叙事指令.指令列表');
                const activeOrdersString = SafeGetValue(characterData, '叙事指令.当前激活指令');
                const inactiveOrdersString = SafeGetValue(characterData, '叙事指令.未激活指令');
                document.getElementById('om-debug-all').textContent = allOrdersString || '(空)';
                document.getElementById('om-debug-active').textContent = activeOrdersString || '(空)';
                document.getElementById('om-debug-inactive').textContent = inactiveOrdersString || '(空)';
                const activeOrders = parseAomStringToArray(activeOrdersString);
                const inactiveOrders = parseAomStringToArray(inactiveOrdersString);
                const combinedList = [];
                activeOrders.forEach(order => { if (order) combinedList.push({ content: order, isActive: true }); });
                inactiveOrders.forEach(order => { if (order) combinedList.push({ content: order, isActive: false }); });
                orderData.orderList = JSON.parse(JSON.stringify(combinedList));
                orderData.originalList = JSON.parse(JSON.stringify(combinedList));
                orderData.hasModifications = false;
                renderOrderList();
                updateOmModifiedIndicator();
            } else {
                container.innerHTML = '<div class="om-empty-state">未找到指令变量</div>';
                const debugAll = document.getElementById('om-debug-all');
                const debugActive = document.getElementById('om-debug-active');
                const debugInactive = document.getElementById('om-debug-inactive');
                if(debugAll) debugAll.textContent = '未找到 stat_data 或 叙事指令';
                if(debugActive) debugActive.textContent = 'N/A';
                if(debugInactive) debugInactive.textContent = 'N/A';
            }
        } catch (error) { console.error('加载叙事指令数据失败:', error); if(container) container.innerHTML = `<div class="om-empty-state" style="color:red;">加载失败: ${error.message}</div>`; }
    }

    // --- 初始化 ---
    checkPovContent();
    applyThemeButtonColors();
    const savedTheme = localStorage.getItem('narrativeTheme_v17') || 'light';
    const savedFontSize = localStorage.getItem('narrativeFontSize_v17') || '16';
    applyTheme(savedTheme);
    if(fontSizeSlider) fontSizeSlider.value = savedFontSize;
    applyFontSize(savedFontSize);
});
</script>
</body>
