    function setupSearch() {
        const searchInput = document.getElementById('achievement-search');
        if (!searchInput) return;
        const achievementItems = document.querySelectorAll('.achievement-item');
        searchInput.addEventListener('input', function() {
            const searchTerm = this.value.toLowerCase().trim();
            const activeTagBtn = document.querySelector('.tag-button.active');
            const activeTag = activeTagBtn ? activeTagBtn.dataset.tag : 'all';
            achievementItems.forEach(item => {
                const title = item.querySelector('.achievement-title').textContent.toLowerCase();
                const description = item.querySelector('.achievement-description').textContent.toLowerCase();
                const condition = item.querySelector('.achievement-condition').textContent.toLowerCase();
                const matchesSearch = title.includes(searchTerm) ||
                                  description.includes(searchTerm) ||
                                  condition.includes(searchTerm);
                const matchesTag = activeTag === 'all' || (item.dataset.tags && item.dataset.tags.includes(activeTag));
                item.style.display = matchesSearch && matchesTag ? 'flex' : 'none';
            });
        });
    }
    function setupInteractiveAchievements() {
        const achievementItems = document.querySelectorAll('.achievement-item');
        achievementItems.forEach(item => {
            item.addEventListener('dblclick', function() {
                const conditionWrapper = this.querySelector('.condition-wrapper');
                if (conditionWrapper) {
                    conditionWrapper.classList.toggle('expanded');
                }
            });
        });
    }
    function setupTagFilter() {
        const tagButtons = document.querySelectorAll('.tag-button');
        const searchInput = document.getElementById('achievement-search');
        tagButtons.forEach(button => {
            button.addEventListener('click', function() {
                tagButtons.forEach(btn => btn.classList.remove('active'));
                this.classList.add('active');
                if (searchInput) {
                    searchInput.dispatchEvent(new Event('input'));
                }
            });
        });
    }
    document.addEventListener('DOMContentLoaded', () => {
        initDisplay();
        setupSearch();
        setupInteractiveAchievements();
        setupTagFilter();
    });
</script>
