    async function initDataStatusDisplay() { try { const messages = await getChatMessages(getCurrentMessageId()); if (!messages || messages.length === 0 || !messages[messages.length - 1].data) return; const gameData = messages[messages.length - 1].data; const characterData = gameData.stat_data; if (!characterData) return; if (characterData.hasOwnProperty('桃子')) { updateProgressBar('momoko-affection-bar', 'momoko-affection', 'momoko-affection-desc', SafeGetValue(characterData, '桃子.好感度'), 0, 100); updateProgressBar('momoko-ntr-bar', 'momoko-ntr', 'momoko-ntr-desc', SafeGetValue(characterData, '桃子.寝取度'), 0, 100); updateProgressBar('momoko-loyalty-bar', 'momoko-loyalty', 'momoko-loyalty-desc', SafeGetValue(characterData, '桃子.对丈夫的忠诚度'), 0, 100); updateTextValue('momoko-mental-state', SafeGetValue(characterData, '桃子.内心状态'), '未知'); } if (characterData.hasOwnProperty('小柴俊')) { updateProgressBar('takeshi-recovery-bar', 'takeshi-recovery', 'takeshi-recovery-desc', SafeGetValue(characterData, '小柴俊.康复度'), 0, 100); updateProgressBar('takeshi-confidence-bar', 'takeshi-confidence', 'takeshi-confidence-desc', SafeGetValue(characterData, '小柴俊.对计划的信心'), 0, 100); updateTextValue('takeshi-mental-state', SafeGetValue(characterData, '小柴俊.心理状态'), '未知'); } if (characterData.hasOwnProperty('互动')) { updateProgressBar('interaction-sex-progress-bar', 'interaction-sex-progress', 'interaction-sex-progress-desc', SafeGetValue(characterData, '互动.性爱进度'), 0, 8); updateProgressBar('interaction-privacy-bar', 'interaction-privacy', 'interaction-privacy-desc', SafeGetValue(characterData, '互动.私密程度'), 1, 5); } if (characterData.hasOwnProperty('世界')) { updateTextValue('world-story-stage', SafeGetValue(characterData, '世界.故事阶段'), '未知'); updateTextValue('world-current-time', SafeGetValue(characterData, '世界.当前时间'), '未知'); } } catch (error) { const statusbarElement = document.getElementById('data-statusbar-v17'); if(statusbarElement) statusbarElement.innerHTML = `<p style='color:red; padding:10px;'>状态栏加载出错: ${error.message}</p>`; } }

    // --- 指令管理器JS逻辑 ---
    let orderData = { orderList: [], originalList: [], hasModifications: false };
    function buildOrderManagerUI() {
