        // 绑定事件
        container.querySelector('.om-debug-header').addEventListener('click', toggleOmDebugArea);
        container.querySelector('.om-btn-add').addEventListener('click', addOmOrder);
        container.querySelector('.om-btn-primary').addEventListener('click', confirmOmModifications);
        container.querySelector('.om-btn-secondary').addEventListener('click', resetOmChanges);
        container.querySelector('#om-new-order-input').addEventListener('keypress', function(e) { if (e.key === 'Enter') { addOmOrder(); } });

        if (localStorage.getItem('omDebugAreaCollapsed') !== 'false') {
            container.querySelector('#om-debug-area').classList.add('collapsed');
