<script>
document.addEventListener('DOMContentLoaded', function() {
    const container = document.getElementById('narrative-container-v17');
    const toggleBtn = document.getElementById('view-toggle-btn-v17');
    const mainView = document.getElementById('main-view-v17');
    const povView = document.getElementById('pov-view-v17');
    const povContentArea = document.getElementById('pov-content-area-v17');
    const menuOpenBtn = document.getElementById('menu-open-btn-v17');
    const menuCloseBtn = document.getElementById('menu-close-btn-v17');
    const popupMenu = document.getElementById('popup-menu-v17');
    const fontSizeSlider = document.getElementById('font-size-slider-v17');
    const fontSizeLabel = document.getElementById('font-size-label-v17');
    const themeSwitchBtns = document.querySelectorAll('.theme-switch-btn');
    const dataStatusbarToggleBtn = document.getElementById('data-statusbar-toggle-btn-v17');
    const dataStatusbar = document.getElementById('data-statusbar-v17');
    const textStatusbarToggleBtn = document.getElementById('text-statusbar-toggle-btn-v17');
    const textStatusbar = document.getElementById('text-statusbar-v17');
    const orderManagerToggleBtn = document.getElementById('order-manager-toggle-btn');
    const orderManagerStatusbar = document.getElementById('order-manager-statusbar');
    let isPovMode = false;
    let isTransitioning = false;
    let isOrderManagerBuilt = false;
    const themeColorMap = { light: { bg: '#f8f6f2', text: '#3d3b37' }, dark: { bg: '#1f1d1b', text: '#e0ddd8' }, dusk: { bg: '#f3eade', text: '#5d4037' }, twilight: { bg: '#0d0f12', text: '#eaf0f2' }, parchment: { bg: '#fdf5e6', text: '#5d4037' } };
    function applyThemeButtonColors() { themeSwitchBtns.forEach(btn => { const themeName = btn.dataset.theme; if (themeColorMap[themeName]) { btn.style.backgroundColor = themeColorMap[themeName].bg; btn.style.color = themeColorMap[themeName].text; } }); }
    function checkPovContent() { if (toggleBtn && povContentArea && (!povContentArea.textContent || povContentArea.textContent.trim() === '')) { toggleBtn.style.display = 'none'; } }
    function toggleView() { if (isTransitioning) return; isTransitioning = true; isPovMode = !isPovMode; const currentView = isPovMode ? mainView : povView; const nextView = isPovMode ? povView : mainView; currentView.classList.add('is-exiting'); currentView.addEventListener('animationend', function onExitAnimationEnd() { this.removeEventListener('animationend', onExitAnimationEnd); this.classList.add('is-hidden'); this.classList.remove('is-exiting'); nextView.classList.remove('is-hidden'); requestAnimationFrame(() => { nextView.classList.add('is-entering'); nextView.addEventListener('animationend', function onEnterAnimationEnd() { this.removeEventListener('animationend', onEnterAnimationEnd); this.classList.remove('is-entering'); isTransitioning = false; }, { once: true }); }); }, { once: true }); }
    if(toggleBtn) toggleBtn.addEventListener('click', toggleView);
    if(menuOpenBtn) menuOpenBtn.addEventListener('click', () => popupMenu.classList.add('active'));
    if(menuCloseBtn) menuCloseBtn.addEventListener('click', () => popupMenu.classList.remove('active'));
    if(popupMenu) popupMenu.addEventListener('click', (e) => { if (e.target === popupMenu) popupMenu.classList.remove('active'); });
    const updateSliderBackground = (slider) => { const value = (slider.value - slider.min) / (slider.max - slider.min) * 100; const textColor = getComputedStyle(slider).getPropertyValue('--text-primary').trim(); const borderColor = getComputedStyle(slider).getPropertyValue('--border-color').trim(); slider.style.background = `linear-gradient(to right, ${textColor} ${value}%, ${borderColor} ${value}%)`; };
    const applyFontSize = (size) => { const numericSize = parseInt(size, 10); const allScrollAreas = document.querySelectorAll('.scroll-area-v17'); allScrollAreas.forEach(area => area.style.fontSize = `${numericSize}px`); if(fontSizeLabel) fontSizeLabel.textContent = `字体大小: ${numericSize}px`; localStorage.setItem('narrativeFontSize_v17', numericSize); if(fontSizeSlider) updateSliderBackground(fontSizeSlider); };
    if(fontSizeSlider) { fontSizeSlider.addEventListener('input', (e) => { applyFontSize(e.target.value); }); }
    const applyTheme = (theme) => { if(container) { container.className = 'narrative-container-v17'; container.classList.add(`theme-${theme}`); } themeSwitchBtns.forEach(btn => btn.classList.toggle('active', btn.dataset.theme === theme)); localStorage.setItem('narrativeTheme_v17', theme); setTimeout(() => { if(fontSizeSlider) updateSliderBackground(fontSizeSlider); }, 50); };
    themeSwitchBtns.forEach(btn => btn.addEventListener('click', () => applyTheme(btn.dataset.theme)));
    if (dataStatusbarToggleBtn && dataStatusbar) { dataStatusbarToggleBtn.addEventListener('click', function() { const isExpanded = dataStatusbar.classList.toggle('expanded'); if(isExpanded) { initDataStatusDisplay(); } if (textStatusbar) textStatusbar.classList.remove('expanded'); if (orderManagerStatusbar) orderManagerStatusbar.classList.remove('expanded'); }); }
    if (textStatusbarToggleBtn && textStatusbar) { textStatusbarToggleBtn.addEventListener('click', function() { const isExpanded = textStatusbar.classList.toggle('expanded'); if(isExpanded) { initTextStatusDisplay(); } if (dataStatusbar) dataStatusbar.classList.remove('expanded'); if (orderManagerStatusbar) orderManagerStatusbar.classList.remove('expanded'); }); }
    if (orderManagerToggleBtn && orderManagerStatusbar) { orderManagerToggleBtn.addEventListener('click', function() { const isExpanded = orderManagerStatusbar.classList.toggle('expanded'); if(isExpanded) { loadOrderData(); } if (dataStatusbar) dataStatusbar.classList.remove('expanded'); if (textStatusbar) textStatusbar.classList.remove('expanded'); }); }
    function initTextStatusDisplay() {
        const sourceElement = document.getElementById('status-block-source');
        const contentElement = document.getElementById('text-status-content');
        if (!sourceElement || !contentElement) return;
        contentElement.innerHTML = '';
        const rawText = sourceElement.textContent || '';
        if (!rawText.trim()) {
            contentElement.innerHTML = '<div class="status-item"><span class="status-item-value">暂无状态信息。</span></div>';
            return;
        }
        const lines = rawText.trim().split('\n');
        lines.forEach(line => {
            line = line.trim();
            if (line) {
                const parts = line.split(/[:：]/);
                const label = parts[0] ? parts[0].trim() : '';
                const value = parts.length > 1 ? parts.slice(1).join(':').trim() : '';
                const itemDiv = document.createElement('div');
                itemDiv.className = 'status-item';
                const labelSpan = document.createElement('span');
                labelSpan.className = 'status-item-label';
