<script>
    function SafeGetValue(obj, path, defaultValue = "N/A") {
        let keys = Array.isArray(path) ? path : path.split('.');
        let current = obj;
        for (let i = 0; i < keys.length; i++) {
            if (current === undefined || current === null || typeof current !== 'object' || !current.hasOwnProperty(keys[i])) {
                return defaultValue;
            }
            current = current[keys[i]];
        }
        if (current === undefined || current === null) {
            return defaultValue;
        }
        if (Array.isArray(current)) {
            return current.length > 0 ? current[0] : defaultValue;
        }
        return current;
    }
    function updateAchievementStatus(characterData, achievementId, variablePath) {
        const element = document.getElementById(achievementId);
        if (!element) return;
        const isUnlocked = SafeGetValue(characterData, variablePath, false) === true;
        if (isUnlocked) {
            element.classList.add('unlocked');
        } else {
            element.classList.remove('unlocked');
        }
    }
    async function initDisplay() {
        try {
            const panel = document.getElementById('achievement-panel');
            setTimeout(() => {
                panel.classList.add('loaded');
            }, 100);
            const messages = await getChatMessages(getCurrentMessageId());
            if (!messages || messages.length === 0 || !messages[0].data) {
                return;
            }
            const gameData = messages[0].data;
            const characterData = gameData.display_data || gameData.stat_data;
            if (!characterData || !characterData.成就) {
